/*
 * prog24_query_string_parser
 *
 * The original binary reads a single line from stdin, treats it as a URL‑style
 * query string (key1=val1&key2=val2 …), percent‑decodes the keys and values,
 * and prints each pair on its own line as:
 *
 *      key=value
 *
 * If `fgets` fails (no input at all) the program prints the literal string
 * "NO_INPUT" and exits.  A trailing '\r' before the final '\n' is ignored,
 * mimicking the behaviour of the original code.
 */

#include <stdio.h>
#include <string.h>
#include <ctype.h>

#define MAX_LINE 2048          /* size of the input buffer */
#define MAX_OUT  2048          /* size for decoded key/value strings */

/* ----------------------------------------------------------------------
 * URL‑decode a fragment.
 *
 *  src   – pointer to the fragment to decode
 *  len   – length of the fragment (bytes to examine)
 *  dest  – buffer where the decoded string is written; it is NUL‑terminated
 *
 * The decoder implements the behaviour observed in the original binary:
 *   * '+' is translated to a space character.
 *   * "%XY" where X and Y are hexadecimal digits is translated to the
 *     corresponding byte value.
 *   * Any other character is copied unchanged.
 * ---------------------------------------------------------------------- */
static void url_decode(const char *src, size_t len, char *dest)
{
    size_t i = 0, o = 0;

    while (i < len) {
        char c = src[i];

        if (c == '+') {
            dest[o++] = ' ';
            ++i;
        } else if (c == '%' && i + 2 < len &&
                   isxdigit((unsigned char)src[i + 1]) &&
                   isxdigit((unsigned char)src[i + 2])) {
            /* convert two hex digits to a byte */
            char hi = src[i + 1];
            char lo = src[i + 2];
            int  val = (isdigit((unsigned char)hi) ? hi - '0' :
                       (toupper((unsigned char)hi) - 'A' + 10));
            val = (val << 4) |
                  (isdigit((unsigned char)lo) ? lo - '0' :
                   (toupper((unsigned char)lo) - 'A' + 10));
            dest[o++] = (char)val;
            i += 3;
        } else {
            dest[o++] = c;
            ++i;
        }
    }
    dest[o] = '\0';
}

int main(void)
{
    static char line[MAX_LINE];
    static char key[MAX_OUT];
    static char val[MAX_OUT];

    /* Read a line from stdin.  The original binary used fgets with a size
       of 0x800 (2048) and printed "NO_INPUT" if fgets returned NULL. */
    if (fgets(line, sizeof(line), stdin) == NULL) {
        puts("NO_INPUT");
        return 0;
    }

    /* Strip the trailing newline (and an optional preceding '\r'). */
    size_t len = strlen(line);
    if (len > 0 && line[len - 1] == '\n') {
        line[--len] = '\0';
        if (len > 0 && line[len - 1] == '\r')
            line[--len] = '\0';
    }

    /* Parse the query string.  The state machine in the original binary
       walks the string character by character, separating tokens on '&'
       and splitting each token on the first '='.  The implementation below
       follows the same logical steps in a straightforward way. */
    size_t i = 0;
    while (i < len) {
        size_t key_start = i;
        size_t key_len   = 0;
        size_t val_start = 0;
        size_t val_len   = 0;

        /* Scan until we hit '=', '&' or the end of the line. */
        while (i < len && line[i] != '=' && line[i] != '&')
            ++i;
        key_len = i - key_start;

        if (i < len && line[i] == '=') {
            ++i;                     /* skip '=' */
            val_start = i;
            while (i < len && line[i] != '&')
                ++i;
            val_len = i - val_start;
        } else {
            /* No '=', the value is empty. */
            val_start = i;   /* same as key end */
            val_len   = 0;
        }

        url_decode(&line[key_start], key_len, key);
        url_decode(&line[val_start], val_len, val);

        printf("%s=%s\n", key, val);

        if (i < len && line[i] == '&')
            ++i;   /* skip '&' and continue */
    }

    return 0;
}
